INSERT OR REPLACE INTO counters (key, value) VALUES ('page', 500);
INSERT OR REPLACE INTO counters (key, value) VALUES ('block', 500);

-- 2026-08 quality repair: business IDs must not expose fixture lifecycle terms.
UPDATE workspaces SET workspace_id='ws_records', name='历史资料' WHERE workspace_id='ws_archive';
UPDATE pages SET parent_id='ws_records' WHERE parent_type='workspace' AND parent_id='ws_archive';

-- Background pages are historical reference material.  Rows generated after
-- the S00 kickoff are moved into the pre-task history without deleting them.
UPDATE pages
SET created_time = strftime('%Y-%m-%dT%H:%M:%S+08:00', created_time, '-120 days')
WHERE page_id <> 'notion_tri_hub_052' AND created_time > '2026-07-06T09:10:00+08:00';
UPDATE pages
SET last_edited_time = CASE
      WHEN strftime('%Y-%m-%dT%H:%M:%S+08:00', last_edited_time, '-120 days') < created_time THEN created_time
      ELSE strftime('%Y-%m-%dT%H:%M:%S+08:00', last_edited_time, '-120 days')
    END
WHERE page_id <> 'notion_tri_hub_052' AND last_edited_time > '2026-07-06T09:10:00+08:00';

-- The seeded page is only an inbox-style starting point, not a completed
-- rubric answer.  A compliant agent must update it (or create another page).
UPDATE pages
SET title='林峥铁三体验营资料入口（待整理）',
    properties_json='{"owner":"user_linz","camp_date":"2026-08-09","status":"待整理"}',
    last_edited_time='2026-07-06T09:10:00+08:00'
WHERE page_id='notion_tri_hub_052';
UPDATE blocks
SET content_json='{"text":"已登记体验营日期和基础目标；训练计划、风险判断、预算授权与阶段复盘尚未整理。"}',
    last_edited_time='2026-07-06T09:10:00+08:00'
WHERE block_id='block_tri_hub_intro';
UPDATE blocks
SET content_json='{"text":"已登记体验营日期和基础目标，详细内容尚未整理。"}'
WHERE block_id='block_tri_hub_intro';

-- 2026-08 second-pass manual-cat repair: historical pages contain personal
-- multisport facts, not grader concepts such as backend persistence or answer
-- construction.  Recurring logs retain dates while varying title structure.
UPDATE pages
SET title = CASE (rowid % 5)
  WHEN 0 THEN json_extract(properties_json,'$.section') || '周记 ' || substr(created_time,1,10)
  WHEN 1 THEN substr(created_time,6,5) || ' ' || json_extract(properties_json,'$.section') || '小结'
  WHEN 2 THEN json_extract(properties_json,'$.section') || '观察（' || substr(created_time,6,5) || '）'
  WHEN 3 THEN '第' || replace(json_extract(properties_json,'$.review_cycle'),'week-','') || '周' || json_extract(properties_json,'$.section') || '记录'
  ELSE json_extract(properties_json,'$.section') || '备忘 ' || substr(last_edited_time,6,5) END
WHERE page_id <> 'notion_tri_hub_052';

DELETE FROM blocks WHERE created_time > '2026-07-06T09:10:00+08:00';
DELETE FROM comments WHERE created_time > '2026-07-06T09:10:00+08:00';
DELETE FROM database_rows WHERE created_time > '2026-07-06T09:10:00+08:00';
DELETE FROM databases WHERE created_time > '2026-07-06T09:10:00+08:00';
DELETE FROM pages WHERE created_time > '2026-07-06T09:10:00+08:00';

DELETE FROM blocks WHERE created_time > '2026-07-06T09:10:00+08:00';
DELETE FROM comments WHERE created_time > '2026-07-06T09:10:00+08:00';
DELETE FROM database_rows WHERE created_time > '2026-07-06T09:10:00+08:00';
DELETE FROM databases WHERE created_time > '2026-07-06T09:10:00+08:00';
DELETE FROM pages WHERE created_time > '2026-07-06T09:10:00+08:00';

UPDATE pages
SET properties_json = json_set(properties_json, '$.business_fact',
  CASE json_extract(properties_json,'$.section')
    WHEN '游泳' THEN CASE ((rowid / 9) % 3)
      WHEN 0 THEN '浅水区连续游四百米，后半程换气节奏略乱'
      WHEN 1 THEN '透明镜片在室内照明下够用，鼻桥需要再调一档'
      ELSE '周末新手游道开放较早，八点后人数明显增加' END
    WHEN '骑行' THEN CASE ((rowid / 9) % 3)
      WHEN 0 THEN '通勤车前刹响应正常，后胎每周需补一次气'
      WHEN 1 THEN '平把车骑四十分钟肩颈无明显紧张，坐垫略低'
      ELSE '滨江段早高峰路口较多，封闭绿道更适合技术练习' END
    WHEN '跑步' THEN CASE ((rowid / 9) % 3)
      WHEN 0 THEN '走跑交替二十五分钟，右膝下坡时有轻微酸胀'
      WHEN 1 THEN '步频放慢后呼吸稳定，连续慢跑仍不超过十分钟'
      ELSE '雨后塑胶道有两处积水，改在内圈完成步行' END
    WHEN '换项' THEN CASE ((rowid / 9) % 3)
      WHEN 0 THEN '鞋带预先放松一档后，换鞋过程缩短约半分钟'
      WHEN 1 THEN '号码带扣具单手可开合，转身时不会滑动'
      ELSE '先戴头盔再移动车辆，动作顺序更容易记住' END
    WHEN '天气' THEN CASE ((rowid / 9) % 3)
      WHEN 0 THEN '午后湿度较高，室外骑行体感比温度读数更闷'
      WHEN 1 THEN '阵雨后绿道树荫段干得较慢，桥面尤其湿滑'
      ELSE '清晨风小且日晒弱，短时户外活动更舒适' END
    WHEN '膝痛' THEN CASE ((rowid / 9) % 3)
      WHEN 0 THEN '晨起平地步行无痛，连续下楼时右膝约一分'
      WHEN 1 THEN '走跑后冰敷十分钟，次日酸胀降到二分以内'
      ELSE '骑行低阻力时膝部稳定，站姿发力会增加不适' END
    WHEN '装备' THEN CASE ((rowid / 9) % 3)
      WHEN 0 THEN '旧手套掌垫已变薄，缝线和魔术贴仍完整'
      WHEN 1 THEN '号码带腰围可调，三个固定点都能夹住号码布'
      ELSE '泳镜盒排水孔通畅，防雾层只能用清水冲洗' END
    WHEN '体验营' THEN CASE ((rowid / 9) % 3)
      WHEN 0 THEN '社区开放日包含泳池体验和短距离骑行展示'
      WHEN 1 THEN '签到通常在东门服务台，迟到者从下一环节加入'
      ELSE '基础活动不含车辆，租赁和自带装备需分别安排' END
    ELSE CASE ((rowid / 9) % 3)
      WHEN 0 THEN '本周完成两次低强度活动，周末保留完整休息日'
      WHEN 1 THEN '一次户外计划因降雨取消，改做二十分钟拉伸'
      ELSE '下一周继续维持短时训练，不同时增加时长和强度' END
  END)
WHERE page_id <> 'notion_tri_hub_052';
